#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);root<-if(length(args))normalizePath(args[[1]])else normalizePath(".")
.libPaths(c(file.path(root,"project","Rlib-4.5"),file.path(root,"renv","library","macos","R-4.5","aarch64-apple-darwin20"),.libPaths()))
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork);library(scales)})
src<-file.path(root,"project","results","phase4","analysis");out<-file.path(root,"project","results","figures")
theme_pub<-theme_classic(base_size=7.0)+theme(plot.title=element_text(face="bold",size=8.2),plot.subtitle=element_text(size=6.1),axis.title=element_text(face="bold"),plot.margin=margin(5,6,5,5))
scores<-fread(file.path(src,"immune_program_scores.tsv"));scores[,z:=as.numeric(scale(score)),by=.(dataset,program_id)];scores[,sample_label:=paste(dataset,sample,sep=" | ")]
p1<-ggplot(scores,aes(sample_label,program_id,fill=z))+geom_tile()+facet_grid(~dataset,scales="free_x",space="free_x")+scale_fill_gradient2(low="#0072B2",mid="white",high="#D55E00",limits=c(-2.5,2.5),oob=squish)+labs(tag="A",title="Frozen immune-programme scores",subtitle="Within-dataset z scores; not immune-cell proportions",x=NULL,y=NULL,fill="Within-dataset z")+theme_minimal(base_size=6.5)+theme(axis.text.x=element_blank(),axis.ticks.x=element_blank(),panel.grid=element_blank(),strip.text=element_text(face="bold"),plot.title=element_text(face="bold",size=8.2),plot.subtitle=element_text(size=6.1),plot.tag=element_text(face="bold",size=9),legend.position="bottom")
pred<-fread(file.path(src,"primary_oof_predictions.tsv"));setorder(pred,-probability);pred[,rank:=.I];pos<-sum(pred$truth==1);neg<-sum(pred$truth==0);pred[,`:=`(tpr=cumsum(truth==1)/pos,fpr=cumsum(truth==0)/neg,precision=cumsum(truth==1)/.I,recall=cumsum(truth==1)/pos)]
roc<-rbind(data.table(fpr=0,tpr=0),pred[,.(fpr,tpr)]);pr<-pred[,.(recall,precision)]
p2<-ggplot(roc,aes(fpr,tpr))+geom_abline(slope=1,intercept=0,linetype="dashed",colour="grey60")+geom_step(colour="#D55E00",linewidth=.7)+coord_equal(xlim=c(0,1),ylim=c(0,1))+labs(tag="B",title="Nested OOF ROC",subtitle="AUC=1.00 in 20 retrospective tissue samples",x="False-positive rate",y="True-positive rate")+theme_pub
p3<-ggplot(pr,aes(recall,precision))+geom_hline(yintercept=mean(pred$truth),linetype="dashed",colour="grey60")+geom_step(colour="#0072B2",linewidth=.7)+coord_cartesian(xlim=c(0,1),ylim=c(0,1))+labs(tag="C",title="Nested OOF\nprecision-recall",subtitle="Average precision=1.00;\ninternal diagnostic only",x="Recall",y="Precision")+theme_pub
br<-unique(quantile(pred$probability,probs=seq(0,1,.2)));pred[,bin:=cut(probability,breaks=br,include.lowest=TRUE)];cal<-pred[,.(mean_probability=mean(probability),observed_fraction=mean(truth),n=.N),by=bin]
p4<-ggplot(cal,aes(mean_probability,observed_fraction))+geom_abline(slope=1,intercept=0,linetype="dashed",colour="grey60")+geom_line(colour="#009E73")+geom_point(aes(size=n),colour="#009E73")+coord_equal(xlim=c(0,1),ylim=c(0,1))+labs(tag="D",title="Exploratory OOF\ncalibration",subtitle="Five quantile groups from\nthe same 20 samples",x="Mean predicted probability",y="Observed case fraction",size="n")+theme_pub+theme(legend.position="bottom")
coef<-fread(file.path(src,"locked_signature_coefficients.tsv"));coef[,gene:=factor(gene,levels=gene[order(coefficient)])]
p5<-ggplot(coef,aes(gene,coefficient,fill=coefficient>0))+geom_col()+coord_flip()+scale_fill_manual(values=c(`TRUE`="#D55E00",`FALSE`="#0072B2"),guide="none")+labs(tag="E",title="Locked 27-gene coefficients",subtitle="Associative model weights; not causal effects",x=NULL,y="Elastic-net coefficient")+theme_pub+theme(axis.text.y=element_text(size=5.2))
stab<-fread(file.path(src,"feature_stability.tsv"))[order(-selection_frequency,gene)][1:30];stab[,gene:=factor(gene,levels=rev(gene))]
p6<-ggplot(stab,aes(gene,selection_frequency))+geom_col(fill="#0072B2")+coord_flip()+scale_y_continuous(limits=c(0,1),breaks=seq(0,1,.2),expand=c(0,0))+labs(tag="F",title="Feature-selection stability",subtitle="Top 30 genes across 500 resamples",x=NULL,y="Selection frequency")+theme_pub+theme(axis.text.y=element_text(size=5.2))
page<-(p1)/(p2|p3|p4)/(p5|p6)+plot_layout(heights=c(1.0,.9,1.25))+plot_annotation(title="Immune-programme and retrospective tissue-classifier diagnostics",subtitle="Internal separation, coefficients and stability do not establish renal-origin specificity, future-risk prediction or causal biology",theme=theme(plot.title=element_text(face="bold",size=10),plot.subtitle=element_text(size=7)))
stem<-"Supplementary_Figure_S8_immune_classifier_diagnostics";ggsave(file.path(out,paste0(stem,".pdf")),page,width=183,height=210,units="mm",device="pdf",useDingbats=FALSE,bg="white");ggsave(file.path(out,paste0(stem,".png")),page,width=183,height=210,units="mm",dpi=600,bg="white")
fwrite(scores,file.path(out,"Supplementary_Figure_S8_source_data_A_immune_scores.tsv"),sep="\t");fwrite(roc,file.path(out,"Supplementary_Figure_S8_source_data_B_roc.tsv"),sep="\t");fwrite(pr,file.path(out,"Supplementary_Figure_S8_source_data_C_pr.tsv"),sep="\t");fwrite(cal,file.path(out,"Supplementary_Figure_S8_source_data_D_calibration.tsv"),sep="\t");fwrite(coef,file.path(out,"Supplementary_Figure_S8_source_data_E_coefficients.tsv"),sep="\t");fwrite(stab,file.path(out,"Supplementary_Figure_S8_source_data_F_stability.tsv"),sep="\t")
idx<-data.table(figure="S8",visual_file=paste0(stem,".pdf"),claim_ids="C16-C19, C21 context",boundary="Retrospective tissue diagnostics; not immune-cell proportions, future-risk prediction, specificity or causality");fwrite(idx,file.path(out,"Supplementary_Figure_S8_source_data.tsv"),sep="\t");writeLines(capture.output(sessionInfo()),file.path(out,"Supplementary_Figure_S8_sessionInfo.txt"));cat("SUPPLEMENTARY_FIGURE_S8_COMPLETE\n")
